  </style>
</head>
<body>
  <div class="app">
    <h1>Todo</h1>
    <div class="subtitle">Organize your tasks</div>

    <div class="input-group">
      <input type="text" id="new-todo" placeholder="What needs to be done?" autocomplete="off">
      <button id="add-todo" aria-label="Add todo">Add</button>
    </div>

    <div class="filters">
      <button class="filter-btn active" data-filter="all">All</button>
      <button class="filter-btn" data-filter="active">Active</button>
      <button class="filter-btn" data-filter="completed">Completed</button>
    </div>

    <ul class="todo-list" id="todo-list">
      <!-- Todo items rendered here -->
    </ul>

    <div class="stats" id="stats">0 items left</div>
  </div>

  <script>
    // Load todos from localStorage or use empty array
    const STORAGE_KEY = 'todo-app-v1';

    function loadTodos() {
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        return stored ? JSON.parse(stored) : [];
      } catch (e) {
        console.error('Failed to load todos:', e);
        return [];
      }
    }

    function saveTodos(todos) {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
      } catch (e) {
        console.error('Failed to save todos:', e);
      }
    }

    let todos = loadTodos();

    // DOM elements
    const newTodoInput = document.getElementById('new-todo');
    const addTodoBtn = document.getElementById('add-todo');
    const todoList = document.getElementById('todo-list');
    const filterBtns = document.querySelectorAll('.filter-btn');
    const statsEl = document.getElementById('stats');

    // Render todos
    function renderTodos(filter = 'all') {
      const filtered = filterTodos(todos, filter);

      if (filtered.length === 0) {
        todoList.innerHTML = '<li class="empty-state">No todos yet — add one above</li>';
      } else {
        todoList.innerHTML = filtered.map((todo, index) => `
          <li class="todo-item${todo.completed ? ' completed' : ''}" data-index="${index}">
            <div class="toggle" 
                 onclick="toggleTodo(${index})"
                 role="checkbox"
                 aria-checked="${todo.completed}"
                 tabindex="0"
                 onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleTodo(${index})}">
              <svg viewBox="0 0 24 24" stroke="currentColor" fill="none" stroke-width="3">
                <path d="M20 6L9 17L4 12"/>
              </svg>
            </div>
            <span class="todo-text">${escapeHtml(todo.text)}</span>
            <button class="delete-btn" onclick="deleteTodo(${index})" aria-label="Delete todo">&times;</button>
          </li>
        `).join('');
      }

      updateStats();
    }

    // Filter todos
    function filterTodos(todos, filter) {
      if (filter === 'all') return todos;
      if (filter === 'active') return todos.filter(t => !t.completed);
      if (filter === 'completed') return todos.filter(t => t.completed);
      return todos;
    }

    // Update stats
    function updateStats() {
      const activeCount = todos.filter(t => !t.completed).length;
      statsEl.textContent = `${activeCount} item${activeCount !== 1 ? 's' : ''} left`;
    }

    // Add todo
    function addTodo(text) {
      const trimmed = text.trim();
      if (!trimmed) return;

      todos = [...todos, { text: trimmed, completed: false }];
      saveTodos(todos);
      renderTodos();
      newTodoInput.value = '';
    }

    // Toggle todo completion
    function toggleTodo(index) {
      todos = todos.map((todo, i) => 
        i === index ? { ...todo, completed: !todo.completed } : todo
      );
      saveTodos(todos);
      renderTodos();
    }

    // Delete todo
    function deleteTodo(index) {
      todos = todos.filter((_, i) => i !== index);
      saveTodos(todos);
      renderTodos();
    }

    // Escape HTML to prevent XSS
    function escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    }

    // Event listeners
    addTodoBtn.addEventListener('click', () => addTodo(newTodoInput.value));

    newTodoInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        addTodo(newTodoInput.value);
      }
    });

    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        renderTodos(btn.dataset.filter);
      });
    });

    // Initial render
    renderTodos();
  </script>
</body>
</html>"}
